export const PPI_GLOSSARY_BLOCKS: ScopeBlock[] = [
  {"kind": "para", "text": "The following is a reference list of common building terms used in the construction industry and a simple explanation of each."},
  {"kind": "subheading", "text": "COMMON BUILDING TERMS"},
  {"kind": "term", "term": "AG LINE", "text": "A perforated pipe (usually covered with a geo-textile fabric) laid behind retaining walls and other areas to catch seeping stormwater."},
  {"kind": "term", "term": "ARCHITRAVE", "text": "moulding surrounding a door or window opening to cover the join between the frame and the wall finish."},
  {"kind": "term", "term": "BAGGING", "text": "A method of finishing brickwork involving the application of a thin mortar slurry using a hessian bag or sponge. Can be painted over or left to fade in an oxide finish. Usually completed by the bricklayer. Bagging varies in texture & colour greatly and is not uniform like render."},
  {"kind": "term", "term": "BALUSTRADE", "text": "A series of vertical members supporting a handrail of a stair, landing, platform or bridge."},
  {"kind": "term", "term": "BEARER", "text": "A sub-floor structural timber member which supports the floor joists."},
  {"kind": "term", "term": "BRICK VENEER", "text": "A method of construction in which a single leaf of non-load bearing wall of brickwork is tied to a timber or metal framed load bearing structure to form the external enclosure."},
  {"kind": "term", "term": "CEMENT", "text": "A finely ground inorganic powder that, mixed with water, binds an aggregate / sand mixture into a hard concrete or mortar within a few days."},
  {"kind": "term", "term": "CHEMICAL DELIGNIFICATION", "text": "Chemical delignification damage is most commonly found in timber sections used as roof tile battens of buildings that are located in close proximity to the sea, large chemical factories or major arterial roads that have heavy traffic."},
  {"kind": "para", "text": "Lignin is the natural glue that holds the fibres of wood together and is therefore a major component of any wood. When the lignin is broken down or damaged the fibres then detaches from each other creating a visible hairy surface to a section of the timber, as the delignification progresses the structure of the timber section is weakened."},
  {"kind": "para", "text": "The timber section can be painted or oiled to stop further deterioration, where the chemical delignification damage is advanced then replacement of the damaged timbers is needed."},
  {"kind": "term", "term": "CONCRETE", "text": "A conglomerated artificial stone made by mixing in specified proportions cement, water and aggregates and pouring the mixture into prepared forms to set and harden."},
  {"kind": "term", "term": "CORNICE", "text": "A moulding placed at the junction between a wall and ceiling."},
  {"kind": "term", "term": "DADO", "text": "The lower portion of a wall above the skirting when finished in contrast to the remainder of the wall e.g. with wood paneling."},
  {"kind": "term", "term": "DAMP-PROOF COURSE (DPC)", "text": "A continuous layer of an impervious material placed in a masonry wall or between a floor and wall to prevent the upward or downward migration of moisture."},
  {"kind": "term", "term": "EAVES", "text": "The lower part of a roof that overhangs the walls."},
  {"kind": "term", "term": "FASCIA", "text": "A metal profile, which is fixed to the lower ends of rafters and usually supports the guttering."},
  {"kind": "term", "term": "FINIAL", "text": "A decorative fitting used at the junction of ridges and hips and at the top of conical, pyramid or domed roofs."},
  {"kind": "term", "term": "FOOTING", "text": "That part of a construction designed to transfer loads to the supporting foundation, usually constructed of reinforced concrete to support base brickwork."},
  {"kind": "term", "term": "FOUNDATION", "text": "The natural or built-up formation of soil, sub-soil or rock upon which a building or structure is supported."},
  {"kind": "term", "term": "FURRING CHANNEL", "text": "Battens fixed to the underside of trusses, rafters or ceiling joists to produce an even level ceiling."},
  {"kind": "term", "term": "GABLE", "text": "The vertical triangular end of a building with a pitched roof, between the rafters from eaves level to the apex (ridge). It may be formed in brickwork or timber framed and clad with weatherboards."},
  {"kind": "term", "term": "GAUGE", "text": "An indicating device usually in brickwork setting out the number of bricks to a certain measurement. E.g.seven brick courses per 600mm in height. This gauge is adjusted to suit the brick and the site conditions."},
  {"kind": "term", "term": "GIRDER TRUSS", "text": "A truss that runs in the opposite direction to other trusses and has brackets (shoes) to carry and support the other trusses. The girder truss is often a double truss, made of hardwood in part or has bigger elements than other trusses."},
  {"kind": "term", "term": "GOING", "text": "In a stair the horizontal distance from the face of one riser to that of the next."},
  {"kind": "term", "term": "HANGING BEAM", "text": "A beam above the ceiling used to support ceiling joists."},
  {"kind": "term", "term": "HEAD", "text": "The upper horizontal member at the top of an opening or frame."},
  {"kind": "term", "term": "HEADER", "text": "A brick laid with its greatest dimension across a wall usually used to tie two skins together or under a door sill or window."},
  {"kind": "term", "term": "HEARTH", "text": "The floor of a fireplace and immediately adjacent area."},
  {"kind": "term", "term": "HERRINGBONE BOND", "text": "A brick bond giving a diagonal pattern in the form of a series of vees or inverted vees."},
  {"kind": "term", "term": "HIP", "text": "The meeting line of two inclined surfaces."},
  {"kind": "term", "term": "HIP ROOF", "text": "A roof which is pyramidal in shape with sloping surfaces and level edges all round."},
  {"kind": "term", "term": "HOOP IRON STRAP", "text": "A strip of thin steel (usually about 25mm wide) which is usually built into brickwork or nailed to frames as a tie-down for wind."},
  {"kind": "term", "term": "IN-FILL CONCRETE SLAB", "text": "A concrete slab poured between base brick walls laid on concrete footings. An in-fill slab is supported by formwork or compacted filling."},
  {"kind": "term", "term": "JOIST", "text": "A timber or steel beam supported by a bearer which the flooring is fixed directly to."},
  {"kind": "term", "term": "KING POST", "text": "A vertical member which connects the ridge and beam of a roof."},
  {"kind": "term", "term": "LAMINATE", "text": "A product made by bonding together two or more layers."},
  {"kind": "term", "term": "MELAMINE LAMINATE", "text": "A laminate manufactured from layers of paper, textile, plastic, wood or wood veneer compressed at high temperature and sealed in melamine plastic. Often used as shelving in robes or kitchens."},
  {"kind": "term", "term": "LINTEL", "text": "A horizontal supporting member spanning over a window or door opening. A \"galintel\" is a steel lintel used to support brickwork over an opening."},
  {"kind": "term", "term": "MORTAR", "text": "A mixing of bush sand (white or yellow), cement (grey or off-white) and water for brickwork. Usually at the rate of 6 part sand to one part cement (by volume) and if required one part lime. Can have a flush, raked or round finish."},
  {"kind": "term", "term": "NEWEL POST", "text": "A post at the top or bottom of a stair flight to support the handrail and/or winders in the stair treads."},
  {"kind": "term", "term": "NOGGING", "text": "A horizontal timber member fixed between joists or trusses to provide stiffening or to support ceiling lining."},
  {"kind": "term", "term": "NOMINAL SIZE", "text": "The size of a timber that is used as a convenient description but not an exact size. Also usually before the timber is dressed."},
  {"kind": "term", "term": "PARAPET", "text": "A low wall to protect the edge of a roof, balcony or terrace. Many shops have a parapet at the front of the building for signage."},
  {"kind": "term", "term": "PARTICLE BOARD", "text": "A flat floor sheeting of good dimensional stability made from wood flakes and synthetic resin / binder under heat and pressure. Can be produced with decorative elements for joinery work."},
  {"kind": "term", "term": "PELMET", "text": "A built-in head to a window to conceal the curtain rod or to a sliding door to conceal the tracks. Usually made of wood."},
  {"kind": "term", "term": "PERP", "text": "A vertical joint in masonry construction."},
  {"kind": "term", "term": "PITCHROOF", "text": "The ratio of the height to span, usually measured in degrees."},
  {"kind": "term", "term": "PICTURE RAIL", "text": "A wooden or plaster moulding fixed to a wall at or above door height for hanging pictures or for decorative purposes."},
  {"kind": "term", "term": "PLYWOOD", "text": "Sheeting made from thin layers of veneer at right angles to each other and bonded together under heat and pressure. Can be used as flooring, wall sheeting, bracing and formwork."},
  {"kind": "term", "term": "POINTING", "text": "The completion of jointing between ridge or hip tiles with a matching colour after bedding of tiles or troweling of mortar into joints after bricks have been laid to touch up."},
  {"kind": "term", "term": "ACROWPROP", "text": "A strut which is light enough to be man-handled, often adjustable in length and used in scaffolding or to support beams temporarily."},
  {"kind": "term", "term": "QUAD MOULDING", "text": "A moulding with a cross-section of a quadrant of a circle used to cover joints often in eaves or at junctions of walls and/or ceilings."},
  {"kind": "term", "term": "RAFTER", "text": "A sloping member in a roof providing the principal structural support for the roofing material."},
  {"kind": "term", "term": "RAFTER (COMMON)", "text": "A rafter spanning the full distance from the eaves to the ridge."},
  {"kind": "term", "term": "RAFTER (CRIPPLE)", "text": "A rafter connecting a hip and a valley."},
  {"kind": "term", "term": "RAFTER (GABLE)", "text": "A common rafter at the end of a pitched roof."},
  {"kind": "term", "term": "RAFTER (HIP)", "text": "A rafter forming the hip at the external line of intersection of two roof surfaces. Jack rafters meet against it."},
  {"kind": "term", "term": "RAFTER (JACK)", "text": "A rafter between a ridge and a valley or a hip rafter and the eave."},
  {"kind": "term", "term": "RAKED JOINT", "text": "A brick joint raked out by the bricklayer for a key for plaster or as a decorative finish."},
  {"kind": "term", "term": "RENDER", "text": "The covering of a brick wall with one or more coats of cement mortar consisting of sand, cement and plasterers clay."},
  {"kind": "term", "term": "RIDGE", "text": "The highest part (apex) of a roof, which is usually a horizontal line."},
  {"kind": "term", "term": "RISER", "text": "The vertical face of a step in a stair flight."},
  {"kind": "term", "term": "SCISSOR TRUSS", "text": "A truss or strut with a sloping bottom chord to produce a raked ceiling at a cheaper cost than rafters."},
  {"kind": "term", "term": "SCOTIA", "text": "A concave moulding."},
  {"kind": "term", "term": "SEASONING", "text": "The elimination of excess moisture from timber by air or kiln drying."},
  {"kind": "term", "term": "SHORING", "text": "The temporary or permanent support of an existing building, often due to demolition or of footing excavation to prevent collapse."},
  {"kind": "term", "term": "SKEW NAILING", "text": "The driving of nails at an oblique angle often in different directions to improve the strength of a joint of fixing."},
  {"kind": "term", "term": "SKIRTING", "text": "A wooden board fixed to the bottom of a wall at the junction of the floor to prevent damage to the wall or to conceal small gaps."},
  {"kind": "term", "term": "SLIP JOINT", "text": "A joint designed to allow movement between two members usually in the form of two layers of sheet metal with grease installed on top of a brick wall prior to installation of a concrete slab."},
  {"kind": "term", "term": "SOFFIT", "text": "The underside of a slab or eave."},
  {"kind": "term", "term": "SOLDIER COURSE", "text": "A course of brickwork laid on its end."},
  {"kind": "term", "term": "SPROCKET", "text": "A framing timber used in eaves construction."},
  {"kind": "term", "term": "STRETCHER BOND", "text": "The most common masonry bond in Australia in which all bricks are laid with half overlaps and not using half bricks or cross bonds."},
  {"kind": "term", "term": "STUCCO", "text": "Traditionally an external render to provide a decorative finish but now generally referred to as a fibro wall sheet with a decorative finish."},
  {"kind": "term", "term": "TERRAZZO", "text": "A material consisting of irregular marble or stone fragments set in a matrix of cement and mechanically abraded and polished after casting to produce a smooth hard surface."},
  {"kind": "term", "term": "THRESHOLD", "text": "The step or sill at an external door of usually timber tile or brickwork."},
  {"kind": "term", "term": "TOUGHENED GLASS", "text": "Glass made by rapidly cooling the glass to make it shatter into small pieces when broken for safety, It usually cannot be cut and needs to be made to order to size. It is unlike laminated glass which is made from layers of glass with silicon between to crack only when broken for safety and can easily be cut on site."},
  {"kind": "term", "term": "TRIMMER", "text": "A timber member fixed between joists or trusses to provide stiffening or to support ceiling lining."},
  {"kind": "term", "term": "UNDERPINNING", "text": "The construction of new footings or concrete piers under an existing footing to prevent its collapse or failure."},
  {"kind": "term", "term": "VALLEY", "text": "The meeting line of two inclined roof surfaces at a re-entrant angle."},
  {"kind": "term", "term": "WEEP HOLES", "text": "Vertical joints or perpends in brickwork left open above the flashing line to allow water from behind the wall to escape."},
  {"kind": "term", "term": "WINDERS", "text": "Wedge shaped treads in a staircase landing."},
  {"kind": "term", "term": "Z-PURLIN", "text": "A metal purlin with a cross section in the shape of the letter Z."},
];

export const PPI_MAINTENANCE_BLOCKS: ScopeBlock[] = [
  {"kind": "para", "text": "The following information is supplied as a general recommendation that should be adopted to help maintain the building in a serviceable condition."},
  {"kind": "subheading", "text": "REQUIREMENTS"},
  {"kind": "para", "text": "Maintenance is the necessary repair and restoration of a building resulting from:"},
  {"kind": "bullet", "text": "Wear and tear."},
  {"kind": "bullet", "text": "Obsolescence of fittings."},
  {"kind": "bullet", "text": "Breakdown of structure or finish resulting from load, thermal changes or earth movement, moisture entry or the effects of weathering."},
  {"kind": "subheading", "text": "WEAR AND TEAR"},
  {"kind": "bullet", "text": "Masonry, plaster, timber and metallic finishes are subject to knocks resulting in chips, indentations and abrasions. Paintwork and other surface finishes become marked, scratched and stained."},
  {"kind": "bullet", "text": "A chipped or broken brick or block in facework can be cut out and replaced with a sound unit."},
  {"kind": "bullet", "text": "In plaster, clean, moisten and patch with plaster or a proprietary patching material."},
  {"kind": "bullet", "text": "In timber, in the body of the surface, fill small holes with proprietary filler. On arises and for large holes, cut out the block with matching timber or veneer."},
  {"kind": "bullet", "text": "In metal, replace the component. Some shallow indentations in a painted surface can be filled with proprietary metal filler."},
  {"kind": "bullet", "text": "After patching or filling, paint as described in PAINTING."},
  {"kind": "bullet", "text": "To achieve a uniform finish, it is important that after patching a wall or ceiling and painting the patched area, then the whole of that wall or ceiling containing the patched area shall be included in the final coat."},
  {"kind": "bullet", "text": "Soiled paintwork is washed or rubbed down and repainted in one or two coats."},
  {"kind": "bullet", "text": "Flaking or peeling paintwork must be scraped or burnt off, and the base surface treated as for new work."},
  {"kind": "bullet", "text": "Paint used in damp areas such as Bath Rooms should be fungus resistant, such as oil based enamel."},
  {"kind": "bullet", "text": "Damaged carpet, vinyl and laminated plastic can be partially replaced. Proprietary acrylic composition bench tops can be repaired."},
  {"kind": "subheading", "text": "OBSOLESCENCE"},
  {"kind": "para", "text": "Many fittings, such as cookers, hot water units and air conditioner units deteriorate in condition with age to the point where replacement is a more attractive alternative (newer models, features etc.) than continued and perhaps costly maintenance. Ten to twelve years is a reasonable life for these items."},
  {"kind": "subheading", "text": "BREAKDOWN IN STRUCTURE AND FINISH"},
  {"kind": "para", "text": "Structural breakdown usually derives from an original construction fault."},
  {"kind": "para", "text": "The life of finishes, both natural and applied, may be more limited, but can be likewise shortened by errors or omissions in original building."},
  {"kind": "para", "text": "Principal of these problems are:"},
  {"kind": "bullet", "text": "Entry of dampness."},
  {"kind": "bullet", "text": "Masonry cracking."},
  {"kind": "bullet", "text": "Concrete cracking."},
  {"kind": "bullet", "text": "Corrosion."},
  {"kind": "bullet", "text": "Paint deterioration."},
  {"kind": "bullet", "text": "Breakdown of adhesion of applied finishes."},
  {"kind": "bullet", "text": "Subsidence."},
  {"kind": "bullet", "text": "Timber anomalies."},
  {"kind": "bullet", "text": "Drainage problems."},
  {"kind": "subheading", "text": "DAMPNESS ENTRY"},
  {"kind": "para", "text": "Entry of dampness is caused by:"},
  {"kind": "bullet", "text": "Failure or absence of damp course of flashing."},
  {"kind": "bullet", "text": "Incorrect location of damp course or flashing."},
  {"kind": "bullet", "text": "Bridging of cavity."},
  {"kind": "bullet", "text": "Roof leaks."},
  {"kind": "bullet", "text": "Gutter leaks."},
  {"kind": "bullet", "text": "Fracture or blockage of water or drainpipes."},
  {"kind": "para", "text": "Horizontal damp course can be replaced and/or inserted in existing walling by removing masonry coursing in alternate 700 mm to 800 mm lengths, or sawing out the joint with a disc or chainsaw, to allow replacement. After replacement mortar has set, remaining intervening panels are similarly treated. Each damp course section must lap over the piece adjoining."},
  {"kind": "para", "text": "The cavity in external perimeter masonry walling must be maintained."},
  {"kind": "para", "text": "Cavity bridging usually occurs by accumulation of mortar at the bottom of the cavity or on cavity ties, and is rectified by the physical removal of bricks as necessary to give access to the cavity, to permit cleaning out of the mortar. Inadvertent closing of the cavity by masonry is rectified by sawing through and inserting a positive mechanical barrier of damp course material."},
  {"kind": "para", "text": "Moisture entry around door and window openings is usually due to absence of or incorrectly located flashings. In metal-framed windows, dampness at sill level is sometimes caused by absence or blockage of weep holes which allow water caught in the sill channel to discharge."},
  {"kind": "para", "text": "Flashing problems can sometimes be overcome with mastic pointing at the junction of the frame and wall externally. There is no substitute for a properly installed positive mechanical flashing."},
  {"kind": "subheading", "text": "ROOF LEAKS"},
  {"kind": "para", "text": "Most metal roof leaks originate from perforations through the roof-pipes, ventilators, aerial fixings and the like. Small holes and short laps in sheet roofing must be sealed, and flashings made watertight. The minimum pitch and fixings must always be to the Manufacture's recommendations."},
  {"kind": "para", "text": "Other causes of leaks are:"},
  {"kind": "bullet", "text": "Inadequate side, apron and gutter flashings."},
  {"kind": "bullet", "text": "Cracked or displaced tiles."},
  {"kind": "bullet", "text": "Inadequate lapping of roof sheeting."},
  {"kind": "bullet", "text": "Unsealed laps at very low pitches."},
  {"kind": "bullet", "text": "Pop-riveting of ridge and hip cappings in lieu of bolts or screws."},
  {"kind": "bullet", "text": "Inadequate pointing of hip and ridge tiles."},
  {"kind": "bullet", "text": "Gutter and downpipe overflows."},
  {"kind": "subheading", "text": "GUTTERS"},
  {"kind": "para", "text": "Gutters should be checked throughout the year especially before winter to ensure they are kept free of blockages."},
  {"kind": "subheading", "text": "CONCRETE PROBLEMS"},
  {"kind": "para", "text": "The greatest of care must be taken when building with concrete, because any serious or continuing problem is usually solved only by the costly process of removal and relaying."},
  {"kind": "para", "text": "Principal maintenance problems are:"},
  {"kind": "bullet", "text": "Cracking"},
  {"kind": "bullet", "text": "Slab surface defects"},
  {"kind": "bullet", "text": "Spalling"},
  {"kind": "bullet", "text": "Corrosion"},
  {"kind": "para", "text": "Cracking can be either right through the element, or on its surface. In concrete on fill, full thickness cracking may be caused by uncontrolled linear drying shrinkage, or earth movement."},
  {"kind": "para", "text": "Rectification is by saw-cutting out a panel and relaying with ruled, and if required, pointed joints. In suspended concrete, structural cracks result from improper or inadequate design, misplacement of reinforcement, and concrete below required design strength or excessive loading during curing period. The remedy for structural failure is removal and reconstruction."},
  {"kind": "para", "text": "Surface defects may be drying shrinkage cracks in topping and surface powdering."},
  {"kind": "para", "text": "Shrinkage cracking in topping is usually in the form of crazing, and whilst not structurally critical, is unsightly. For an exposed finish, rectification would require hacking off the topping and laying a new topping."},
  {"kind": "para", "text": "Surface powdering is caused by a low cement aggregate ratio, incorrect proportioning of aggregate fines, excessive water in mix, or excessive addition of pigment. Minor powdering can be arrested by flooding the surface with a proprietary hardening agent."},
  {"kind": "para", "text": "Major powdering on an exposed surface would require removal and relaying of the top 25 mm to 35 mm."},
  {"kind": "para", "text": "Spalling is caused by expansion of rusting reinforcement not sufficiently covered, or by decay of quartz or other impurities in concrete. Replacement or patching would be required."},
  {"kind": "para", "text": "Corrosion of concrete by external factors (chemical attack by sugars or acids) is rarely a problem in domestic buildings."},
  {"kind": "subheading", "text": "MASONRY DEFECTS"},
  {"kind": "para", "text": "Cracks in walls may result from:"},
  {"kind": "bullet", "text": "Inadequate foundations."},
  {"kind": "bullet", "text": "Uncontrolled thermal movement in long walls."},
  {"kind": "bullet", "text": "Inadequate support over openings."},
  {"kind": "bullet", "text": "Differential movement of junction of different materials."},
  {"kind": "bullet", "text": "Seismic activity."},
  {"kind": "para", "text": "Movement occurs in plastic clayey soils as a result of moisture and thermal changes. Subsidence or pressures resulting will in the absence of adequate foundations, cause cracks in walls."},
  {"kind": "para", "text": "Thermal movement in long masonry walls will cause cracking in the absence of control joints. Absence of, or inadequate support can result in cracks at the heads of openings."},
  {"kind": "para", "text": "A crack can always be anticipated at the junction of brickwork and concrete. This should be controlled with a “bond breaker \" membrane. Rectification of above faults may, dependent on severity, require:"},
  {"kind": "bullet", "text": "Saw cutting in new control joints."},
  {"kind": "bullet", "text": "Removal of brickwork or block-work both sides of crack and re-laying."},
  {"kind": "bullet", "text": "Raking back cracked joint 35 mm and pointing with mastic joint sealer."},
  {"kind": "subheading", "text": "PAINT DETERIORATION"},
  {"kind": "para", "text": "External paintwork is broken down by the action of sunlight, air and moisture. Full deterioration may take from 3 to 10 years, manifested by powdering, flaking or peeling. Powdered areas may be rubbed down and repainted in preferably 2 coats. Flaked or peeling paint must be scraped or burnt off to the original surface, which is then treated as for new work. Adequacy of protection will depend on paint film thickness and opacity."},
  {"kind": "para", "text": "It is recommended that external painted finishes be renewed every 5 to 7 years."},
  {"kind": "subheading", "text": "METAL CORROSION"},
  {"kind": "para", "text": "Damp courses, flashing, roof sheeting, gutters and plumbing piping in buildings are all subject to corrosion by either chemical or electrolytic action."},
  {"kind": "para", "text": "For example, unprotected metallic damp-coursing is subject to the corrosive action of mortars, and electrolytic corrosion will occur in the junction of copper and steel piping. In replacement, ensure that the attacked metal is adequately insulated with a neutral material. In new building work, steel exposed externally will rust unless adequately protected, according to conditions, and particularly coastal."},
  {"kind": "subheading", "text": "FRETTING"},
  {"kind": "para", "text": "Improperly slaked or hydrated lime can result in powdering and fretting of mortar due to the continuing hydration process. Rake out the soft mortar 25mm to 40mm deep and point up with strong composition mortar."},
  {"kind": "para", "text": "Fretting of actual brick surface can result from the trapping of salts in the pores of bricks during manufacture, which becomes active with moisture."},
  {"kind": "subheading", "text": "TIMBER PROBLEMS"},
  {"kind": "para", "text": "Timber, properly installed in a building is a strong, durable and decorative material. Problems usually originate from building faults or neglected protection."},
  {"kind": "para", "text": "Inadequate paint coverage or lack of maintenance will result in external timber such as posts, beams doors and window frames, door faces, barge boards, fascias etc., developing surface cracks and opening up joints. If deterioration has not advanced too far, these items can be repaired."},
  {"kind": "bullet", "text": "Termite attacking timber."},
  {"kind": "para", "text": "Karri near the ground is particularly vulnerable. Building sites require pre-treatment against termites in accordance with AS 2057 1981. Rectification includes Replacement of affected timber and specialist treatment. Because nests can be under concrete floors treatment may require boring through concrete or cutting trap door in floor."},
  {"kind": "subheading", "text": "EFFLORESCENCE ETC."},
  {"kind": "para", "text": "This is a furry powdery deposit of water soluble salts which form on the surface or brickwork. Water soluble or acid solution salts of vanadium, iron or manganese in film can also form on the surface of brickwork, showing as a stain. Drips from unsealed hardwood can also stain light coloured masonry."},
  {"kind": "para", "text": "The white powder of efflorescence is water soluble, can be washed off, and will eventually disappear."},
  {"kind": "para", "text": "The green and yellow vanadium stains which sometimes appear on cream brickwork respond to chemical treatment such as oxalic acid, hypochlorite type bleaching agents and caustic soda in different cases."},
  {"kind": "para", "text": "Note that hydrochloric acid should not be used on cream brickwork because it tends to set the vanadium salts in the surface and turn them black."},
  {"kind": "para", "text": "Timber stains usually respond to a solution of oxalic acid in water, or household bleach based on sodium hypochlorite. Hose down after chemical treatment."},
  {"kind": "subheading", "text": "FUNGUS"},
  {"kind": "para", "text": "Porous masonry and some porous plastic paints, for example, PVA, are susceptible to fungus attack in conditions of sustained moisture or humidity. Proprietary preparations such as those containing Sodium and Calcium Hypochlorites, and Sodium carbonate can be used to bleach the mildew stain. Vinegar solutions will kill mould growth if used at correct strength. We advise customer to consultwww.mould.com for severe mould problems."},
  {"kind": "para", "text": "The application of silicone sealing, or an impervious oil based paint will inhibit regrowth."},
  {"kind": "subheading", "text": "ADHESION LOSS"},
  {"kind": "para", "text": "Breakdown of adhesion will result in loosening and detachment of:-"},
  {"kind": "bullet", "text": "Ceramic tiles from floors and walls."},
  {"kind": "bullet", "text": "Vinyl tiles and sheet from floors and walls."},
  {"kind": "bullet", "text": "Timber mosaic and parquet from floors"},
  {"kind": "bullet", "text": "Papers and vinyl from walls"},
  {"kind": "bullet", "text": "Laminated plastics from backing"},
  {"kind": "para", "text": "Causes of breakdown include:"},
  {"kind": "bullet", "text": "Ceramic tiles bedded in cement mortar - substandard mortar, tile suction (i.e. tiles not soaked before laying), no provision for thermal movement in restrained positions, pre-setting or drying of screed."},
  {"kind": "bullet", "text": "Rectification requires relaying to correct procedure, and incorporation of mastic filled control joints as may be necessary."},
  {"kind": "bullet", "text": "Moisture in sub-surface. This can cause lifting of adhered ceramics, vinyl and timber mosaics. Testing can establish adequacy of dryness of sub-surface. Laying must be carried out with the recommended bonding agent."},
  {"kind": "bullet", "text": "Wall papers and vinyl's lose adhesion because of excessive suction of the subsurface. Porous backgrounds require sealing."},
  {"kind": "subheading", "text": "PLASTICS"},
  {"kind": "para", "text": "Rigid PVC piping used externally will break down under prolonged exposure to heat and sunlight. Mechanical impact to plastic products can cause fracture. UPVC should therefore be protected from impact damage and direct sunlight. Replacement is readily effected."},
  {"kind": "para", "text": "Detached contact-adhered laminates are rebounded and cramped."},
  {"kind": "subheading", "text": "ROMAN BATHS"},
  {"kind": "para", "text": "Some houses have what is typically described as a 'Roman' bath constructed below the shower. The bath is constructed from brick and is rendered and tiled. In our experience, 95% of the baths are prone to leaking. It is recommended that the corners of the bath be sealed with a flexible silicon based grout of appropriate colour, and that the arrangement not be used as a bath."},
  {"kind": "subheading", "text": "PLUMBING AND DRAINAGE TERMS"},
  {"kind": "term", "term": "ABSORPTION TRENCH", "text": "A trench, pit or well excavated from permeable ground filled with broken stone, bricks or large granular materials and covered with earth to dispose of the discharge from a septic tank, sullage system or stormwater by absorption into the ground. Also called ABSORPTION PIT, ABSORPTION WELL OR SOAKAWAY."},
  {"kind": "term", "term": "GULLY TRAP (GT)", "text": "An assembly in a sanitary drainage system, consisting of a trap and other fittings. Also called GULLY."},
  {"kind": "term", "term": "FLOOR WASTE GULLY", "text": "A disconnector gully with a floor grate or waste outlet fitting located inside the building and, where required, with provision for the connection of waste pipes from sanitary fixtures."},
  {"kind": "term", "term": "INVERT", "text": "The lowest point of the internal surface of a pipe or channel at any cross-section."},
  {"kind": "term", "term": "JUNCTION (PIPE)", "text": "A pipe fitting incorporating one or more branched."},
  {"kind": "term", "term": "MANHOLE", "text": "A large chamber or opening on a drain, sewer or equipment to permit access for inspection, testing or clearance if obstruction."},
  {"kind": "term", "term": "STACK", "text": "A vertical sanitary drainage pipe, including offsets, which extends more than one storey in height."},
  {"kind": "term", "term": "SULLAGE", "text": "Domestic waste water other than from soil fixtures."},
  {"kind": "term", "term": "SUMP", "text": "A pit at or below the lowest point of a structure to collect unwanted water and facilitate its removal, usually by means if a SUMP PUMP. Also called DRAIN PIT."},
  {"kind": "term", "term": "TRAP", "text": "a) A fitting usually in the shape of the letter P or S which retains water to form a \"water seal\" so as to prevent the passage if gases or foul air into the building. b) A fitting for the interception of silt, acids, grease, oils or fats."},
  {"kind": "term", "term": "BOUNDARY TRAP", "text": "A trap in the property service drain, usually near the boundary if a property and below the lowest inlet, to prevent the entry of air or gases from the sewer into property service drain. Also called INTERCEPTOR TRAP."},
  {"kind": "term", "term": "GREASE TRAP", "text": "A device in the shape if a box with baffle plates to slow the flow of liquid waste and prevent the passage if greasy substance into the drainage system. Also called GREASE INTERCEPTOR TRAP."},
  {"kind": "term", "term": "P-TRAP", "text": "A trap in which the inlet leg is vertical and the outer leg inclined below the horizontal to specified limits, with or without inspection opening at the lowest point."},
  {"kind": "term", "term": "S-TRAP", "text": "A trap in which the outer leg is vertical and parallel with the inlet leg, with or without inspection opening at the lowest point."},
  {"kind": "term", "term": "SILT TRAP", "text": "A trap containing a removable container for the collection if silt, sand or grit."},
  {"kind": "term", "term": "VALVE", "text": "A device for the control of liquid or gas flow, having an aperture which can be wholly or partially closed by a plate, disc, door, gate, piston, plug ball r the flexing if a diaphragm."},
  {"kind": "term", "term": "BALL VALVE", "text": "A valve having a turning ball with a port or ports to control the flow of fluid."},
  {"kind": "term", "term": "FLOAT VALVE", "text": "A valve actuated by a float (floating ball) to control the flow of liquid, used in tanks or cisterns to maintain a minimum water level. Also referred to as FLOATING BALL VALVE."},
  {"kind": "term", "term": "FLUSH VALVE", "text": "A control devise for water flow at mains pressure to a WC pan; used instead of a cistern."},
  {"kind": "term", "term": "GATE VALVE", "text": "A water control valve which closes like a sliding gate over an opening."},
  {"kind": "term", "term": "MIXING VALVE", "text": "A valve which is designed to mix separate supplies of hot and cold water and direct the maximum."},
  {"kind": "term", "term": "NON-RETURN VALVE", "text": "A valve which prevents the reversals of flow by means of a flap or mechanism."},
  {"kind": "term", "term": "PRESSURE REDUCING VALVE", "text": "A valve designed to reduce or limit the pressure of a fluid to a predetermined valve in the downstream side. Also called PRESSURE LIMITING VALVE."},
  {"kind": "term", "term": "PRESSURE RELIEF VALVE", "text": "A spring-loaded or weight-controlled automatic valve to limit the build-up of pressure in pipe work, fittings or vessels by discharging excessive pressure to the atmosphere."},
  {"kind": "term", "term": "SAFETY VALVE", "text": "A pressure-relief valve for a boiler or unfired pressure vessel."},
  {"kind": "term", "term": "STOP VALVE", "text": "A valve, such as a gate valve, which can be operated to stop flow in a pipeline. Also known as ISOLATING VALVE."},
  {"kind": "term", "term": "TEMPERATURE RELIEF", "text": "A temperature activated valve to relieve excess pressure in water heaters in the event of a thermostat failure and overheating."},
  {"kind": "term", "term": "VENT(VENT PIPE)", "text": "A pipe provided to limit pressure fluctuations within a discharge pipe system by the induction or discharge of air and/or to facilitate the discharge of gases."},
];

export const PPI_TERMS_BLOCKS: ScopeBlock[] = [
  {"kind": "para", "text": "WHEREAS: The Client has requested the Inspector and the Inspector has agreed to carry out an inspection of the Property on the Inspection Date for the purposes of preparing the Report for the Inspection Fee on the terms and conditions set out below (“the Agreement”)."},
  {"kind": "para", "text": "Payment is required prior to release of the Report unless otherwise agreed in writing by the Inspector."},
  {"kind": "para", "text": "This Agreement is sent to the Client with the Quotation email. No signature is required. The Client is deemed to have accepted the Quotation and this Agreement when the Client replies to and confirms the Quotation by email (see clause 17). The Quotation is valid for 30 days from the date of the Quotation."},
  {"kind": "para", "text": "Standards and guidance referred to in this Agreement: AS 4349.0–2007 Inspection of buildings – General requirements; AS 4349.1–2007 Inspection of buildings – Pre-purchase inspections – Residential buildings; and the Guide to Standards and Tolerances 2026 (Victorian Government, Building and Plumbing Commission)."},
  {"kind": "section", "n": "1", "title": "DEFINITIONS & INTERPRETATION"},
  {"kind": "clause", "n": "1.1", "paras": ["In this Agreement, except where the context otherwise requires:"]},
  {"kind": "definition", "term": "“ACL”", "text": "means the Australian Consumer Law set out in Schedule 2 to the Competition and Consumer Act 2010 (Cth), as applied in Victoria by the Australian Consumer Law and Fair Trading Act 2012 (Vic)."},
  {"kind": "definition", "term": "“Agreement”", "text": "means the Quotation and these terms and conditions and any Use Conditions contained in the Report."},
  {"kind": "definition", "term": "“AS 4349”", "text": "means the Australian Standard AS 4349 Inspection of buildings, including AS 4349.0–2007 (General requirements) and, for pre-purchase inspections of residential buildings, AS 4349.1–2007 (Pre-purchase inspections – Residential buildings), as applicable."},
  {"kind": "definition", "term": "“Business Day”", "text": "means a day that is not a Saturday, Sunday or public holiday in Victoria."},
  {"kind": "definition", "term": "“Client”", "text": "means the person, company or entity that engages Houspect to undertake the Works. For the purposes of this Agreement, the Client is the person, company or entity to whom the Quotation email is addressed and who accepts the Quotation in accordance with clause 17."},
  {"kind": "definition", "term": "“Confidential Information”", "text": "means any information of Houspect whether documentary or otherwise, that may reasonably be considered commercially sensitive or indicated as such, including the terms of this Agreement, intellectual property, plans, drawings, designs, business plan and contracts, company policies, operations, work methods, processes, client information or business costs (charged or otherwise) except to the extent that such information is already in the public domain."},
  {"kind": "definition", "term": "“Guide”", "text": "means the Guide to Standards and Tolerances 2026 published by the Victorian Government (Building and Plumbing Commission, revised by the Office of the State Building Surveyor), or the edition of that Guide referred to in clause 5.7."},
  {"kind": "definition", "term": "“Houspect”", "text": "means Acespect Pty Ltd trading as Houspect Victoria ABN 24 237 148 557 of PO Box 2521, MOUNT WAVERLEY VIC 3149, its related subsidiaries and franchisees and includes its inspectors."},
  {"kind": "definition", "term": "“Elevated area”", "text": "includes the roof, roof space, crawl space, landing feature, and the like, generally elevated above the ground and not intended for normal use by occupants."},
  {"kind": "definition", "term": "“Inspection Date”", "text": "means the date of the Inspection stated in the Quotation or Confirmation Correspondence, or otherwise agreed between the parties."},
  {"kind": "definition", "term": "“Inspection”", "text": "means the inspection of the Property as per Clause 4."},
  {"kind": "definition", "term": "“Inspector”", "text": "means the person who will attend the Inspection and draft the Report on instruction from Houspect."},
  {"kind": "definition", "term": "“Legislative Requirements”", "text": "includes:"},
  {"kind": "item", "n": "(a)", "text": "Acts, ordinances, regulations, by-laws, orders, awards and proclamations of the Commonwealth and the State or Territory applicable to the Works; and"},
  {"kind": "item", "n": "(b)", "text": "Certifications, licenses, consent, permits, approvals and requirements of organisations having jurisdiction applicable to the Works, including all the relevant Australian Standards, the Building Codes of Australia, the National Construction Code and applicable industry standards and tolerances."},
  {"kind": "definition", "term": "“Personnel”", "text": "means all Houspect’s employees and contractors properly acting for and on behalf of Houspect in relation to the Scope."},
  {"kind": "definition", "term": "“Price”", "text": "means those fees Houspect has agreed with the Client in exchange for undertaking the Works. The Price is the fee stated in the Quotation."},
  {"kind": "definition", "term": "“Property”", "text": "means the structure(s) and its appurtenances to be Inspected on the Site."},
  {"kind": "definition", "term": "“Quotation”", "text": "means the Booking Confirmation (or any other equivalent document or final price advice) provided by Houspect to the Client in relation to the Works. It includes the email addressed to the Client to which this Agreement is attached or linked, and the scope, fee and date stated in it."},
  {"kind": "definition", "term": "“Report”", "text": "means the Report prepared by Houspect on behalf of the Client."},
  {"kind": "definition", "term": "“Scope”", "text": "means the scope of the Inspection to be undertaken by the Inspector in accordance with Clause 4."},
  {"kind": "definition", "term": "“Site”", "text": "means the land, the Property or other places made available by the Client to Houspect for the purposes of performing the Works, as referred to in the Quotation."},
  {"kind": "definition", "term": "“Use Conditions”", "text": "means any additional conditions contained in the Report relating to its use or application."},
  {"kind": "definition", "term": "“Variations”", "text": "means variations to the Works in accordance with Clause 13."},
  {"kind": "definition", "term": "“Works”", "text": "means the inspection of the Property, and the drafting of the Report."},
  {"kind": "clause", "n": "1.2", "paras": ["This Agreement contains the entire understanding of the parties and, unless specifically referenced in this Agreement, supersedes any other agreement, representation, tender, quote, conditions of contract, standard terms or request between the parties made or dated prior to the date of this Agreement."]},
  {"kind": "clause", "n": "1.3", "paras": ["This Agreement shall be construed and governed in all respects in accordance with the laws of Victoria, Australia and the Commonwealth of Australia, and each party submits to the non-exclusive jurisdiction of the courts of Victoria."]},
  {"kind": "clause", "n": "1.4", "paras": ["In this Agreement:"]},
  {"kind": "item", "n": "(a)", "text": "where the Client includes one or more persons, this Agreement binds them jointly and severally;"},
  {"kind": "item", "n": "(b)", "text": "no rule of construction applies against a party merely on the basis that, that party prepared this Agreement or a portion of it;"},
  {"kind": "item", "n": "(c)", "text": "the singular includes the plural and vice versa and “including” and similar expressions are not words of limitation;"},
  {"kind": "item", "n": "(d)", "text": "where a word or phrase is defined in this Agreement, other parts of speech or grammatical forms of that word or phrase have a corresponding meaning;"},
  {"kind": "item", "n": "(e)", "text": "an expression importing a natural person includes any company, partnership, joint venture, association, corporation or other body corporate and any Government agency and includes that party's successors or permitted assigns; and"},
  {"kind": "item", "n": "(f)", "text": "a reference to a document or a statutory instrument includes an amendment or supplement to, or replacement or novation of it."},
  {"kind": "section", "n": "2", "title": "HOUSPECT'S OBLIGATIONS"},
  {"kind": "clause", "n": "2.1", "paras": ["Houspect will:"]},
  {"kind": "item", "n": "(a)", "text": "subject to clause 4, carry out the Works with all reasonable care and skill in accordance with this Agreement; and:"},
  {"kind": "item", "n": "(b)", "text": "attend to the Scope of Inspection and provide the Report in consideration of the Price."},
  {"kind": "section", "n": "3", "title": "CLIENT'S OBLIGATIONS"},
  {"kind": "clause", "n": "3.1", "paras": ["In addition to its other responsibilities in this Agreement, the Client must:"]},
  {"kind": "item", "n": "(a)", "text": "pay the Price in accordance with clause 11 (Payment);"},
  {"kind": "item", "n": "(b)", "text": "notify Houspect of any known or suspected hazards existing at the Site including, but not limited to, hazardous waste, adverse site conditions, noxious substances or underground utilities, and take all necessary steps to minimise the risk of exposure to such hazards;"},
  {"kind": "item", "n": "(c)", "text": "facilitate, or authorise Houspect to arrange with the owner, occupier or selling agent, sufficient access to the Site and its improvements to enable Houspect to duly perform the Works in accordance with this Agreement."},
  {"kind": "clause", "n": "3.2", "paras": ["The Client warrants that it is the owner of the Property, or is authorised by the owner and any occupier, to engage Houspect, to give Houspect access to the Site, and to receive the Report. The Client should, so far as it is able, assist Houspect to obtain the consents needed for the Inspector to enter the Site and to take photographs and notes, including from any tenant, occupier, owners corporation or body corporate."]},
  {"kind": "clause", "n": "3.3", "paras": ["Houspect will coordinate the Inspection appointment with the owner, occupier or selling agent. So far as it is able, the Client should let occupiers know that the Inspector will attend and may take photographs of the Property."]},
  {"kind": "section", "n": "4", "title": "SCOPE OF INSPECTION"},
  {"kind": "clause", "n": "4.1", "paras": ["The Inspection will be limited to the Scope outlined in the Quotation or as otherwise agreed in writing, and"]},
  {"kind": "clause", "n": "4.2", "paras": ["The Inspection will be undertaken generally in accordance with AS 4349.0 – 2007 and AS 4349.1 – 2007 as applicable. Where there exists any conflict between the Australian Standards and this Agreement, the Agreement prevails."]},
  {"kind": "clause", "n": "4.3", "paras": ["Unless otherwise agreed in writing, the inspection will not include invasive or destructive examination or investigation for latent or hidden defects. Houspect will have no liability for any defects not reasonably manifest and visible at the time of Inspection through a visual inspection. Houspect is also not obliged to inspect any inaccessible or concealed areas of the Property, or to provide any comment in the Report in relation to:"]},
  {"kind": "item", "n": "(a)", "text": "hidden or obscured defects;"},
  {"kind": "item", "n": "(b)", "text": "latent Site or Property conditions; or"},
  {"kind": "item", "n": "(c)", "text": "whether the Property complied with Australian Standards, relevant Building Codes or Legislative Requirements at the time the Property was constructed."},
  {"kind": "clause", "n": "4.4", "paras": ["The Inspector will compare the prevailing conditions of the Property and use his/her best endeavours to indicate in the Report whether any defect is in the nature of the following:"]},
  {"kind": "item", "n": "(a)", "text": "a major defect, which is a defect of sufficient magnitude where rectification has to be carried out in order to avoid unsafe conditions, loss of utility or further deterioration of the Property;"},
  {"kind": "item", "n": "(b)", "text": "a minor defect, which is a defect other than a major defect, for which a general comment is made; and"},
  {"kind": "item", "n": "(c)", "text": "a safety hazard, which includes only physical observed defects which the Inspector considers to be a safety hazard."},
  {"kind": "clause", "n": "4.5", "paras": ["Subject to this Clause 4, the Inspector shall inspect and report on the specific areas nominated in the Quotation (if any) and if requested, such parts of the building and its appurtenances, together with the Property generally within its boundaries where safely accessible. This may include the following areas:"]},
  {"kind": "item", "n": "(a)", "text": "the interior of the building;"},
  {"kind": "item", "n": "(b)", "text": "the roof space;"},
  {"kind": "item", "n": "(c)", "text": "the exterior of the building;"},
  {"kind": "item", "n": "(d)", "text": "the sub-floor space;"},
  {"kind": "item", "n": "(e)", "text": "the roof exterior; and"},
  {"kind": "item", "n": "(f)", "text": "any relevant feature of the Property within 30m of the main building (and within the boundaries of the Site)."},
  {"kind": "clause", "n": "4.6", "paras": ["Inspection of strata and company title Property shall be limited to the nominated residence and, subject to Clause 6, does not include common property."]},
  {"kind": "clause", "n": "4.7", "paras": ["The Inspector shall inspect any Elevated Area only where:"]},
  {"kind": "item", "n": "(a)", "text": "it is at a height at which safe reasonable access is available, or where safe and reasonable access is otherwise available; or"},
  {"kind": "item", "n": "(b)", "text": "an unobstructed line of sight is present from safe use of a 3.6m ladder and the building elements present are close enough to allow appraisal."},
  {"kind": "clause", "n": "4.8", "paras": ["Any areas where reasonable access is denied, not made available or inaccessible for any reason, are excluded from, and do not form part of, the Inspection and the Report. Where the Inspector is unable or unwilling pursuant to this Agreement to access areas of the Property, these areas may be noted in the Report."]},
  {"kind": "clause", "n": "4.9", "paras": ["Any comments made in the Report in relation to the following are general in nature only and may not be relied upon in any advisory sense by the Client. The Client should engage suitably experienced contractors to review any comments made in the Report related to:"]},
  {"kind": "item", "n": "(a)", "text": "plumbing;"},
  {"kind": "item", "n": "(b)", "text": "electrical;"},
  {"kind": "item", "n": "(c)", "text": "engineering;"},
  {"kind": "item", "n": "(d)", "text": "mould;"},
  {"kind": "item", "n": "(e)", "text": "toxicology;"},
  {"kind": "item", "n": "(f)", "text": "waterproofing;"},
  {"kind": "item", "n": "(g)", "text": "gas fittings;"},
  {"kind": "item", "n": "(h)", "text": "air conditioning;"},
  {"kind": "item", "n": "(i)", "text": "pests, such as termites; and"},
  {"kind": "item", "n": "(j)", "text": "asbestos"},
  {"kind": "item", "n": "(k)", "text": "swimming pool(s)."},
  {"kind": "subheading", "text": "Structural Defect Inspections"},
  {"kind": "clause", "n": "4.10", "paras": ["The Works will be limited to visual, line of sight inspections of the structural elements of the Property. Where necessary and accessible, this will include accessing subfloors and roof spaces to ascertain the extent of any readily identifiable defective workmanship."]},
  {"kind": "subheading", "text": "Standards and Guide"},
  {"kind": "clause", "n": "4.11", "paras": ["Without limiting clause 4.2, the Inspection is a pre-purchase inspection of a residential building and, in accordance with AS 4349.1–2007, comprises a visual assessment of the Property to identify major defects and to form an opinion regarding the general condition of the Property at the time of the Inspection, together with a visual appraisal and limited assessment of serviceability. It is not a condition survey with list of maintenance items nor an inventory of items that needs attention."]},
  {"kind": "clause", "n": "4.12", "paras": ["As required by AS 4349.0–2007 (clause 2.1), the parties record the following inspection agreement details:"]},
  {"kind": "item", "n": "(a)", "text": "Purpose: to provide the Client, as a prospective purchaser or other interested party, with an opinion regarding the condition of the Property at the time of the Inspection."},
  {"kind": "item", "n": "(b)", "text": "Scope: the scope set out in the Quotation and in this clause 4."},
  {"kind": "item", "n": "(c)", "text": "Acceptance criteria: the building is compared with a building that was constructed in accordance with the generally accepted practice at the time of construction and which has been maintained such that there has been no significant loss of strength and serviceability."},
  {"kind": "clause", "n": "4.13", "paras": ["A Report prepared with reference to AS 4349 is not a certificate of compliance of the Property with any Act, regulation, ordinance, local law or by-law, and is not a warranty or an insurance policy against problems developing with the building in the future. The Inspection assumes that the existing use of the building will continue, and does not include the identification of unauthorised building work or of work that does not comply with building regulations."]},
  {"kind": "subheading", "text": "Pre-Purchase Inspection"},
  {"kind": "clause", "n": "4.14", "paras": ["The Inspection should be arranged as early in the buying process as practicable. Houspect gives no advice on whether the Client should purchase the Property, or on its value, and the Client remains responsible for its own purchase decision, contract conditions and finance."]},
  {"kind": "subheading", "text": "Access and Site Conditions"},
  {"kind": "clause", "n": "4.15", "paras": ["Houspect will coordinate the Inspection appointment and access with the Client and, where applicable, the owner, occupier or selling agent. So far as the Client is able, the Client should help to ensure that, on the Inspection Date:"]},
  {"kind": "item", "n": "(a)", "text": "the Inspector has safe and unobstructed access to every area within the Scope, including keys, codes and passes for locked rooms, gates, sheds, roof space hatches and sub-floor access covers;"},
  {"kind": "item", "n": "(b)", "text": "electricity and water are connected and operating, where reasonably needed for the Inspection;"},
  {"kind": "item", "n": "(c)", "text": "animals are restrained or removed from the areas to be inspected;"},
  {"kind": "item", "n": "(d)", "text": "the areas to be inspected are clear of stored items, furniture and floor coverings so that building elements can be seen."},
  {"kind": "clause", "n": "4.16", "paras": ["The Inspector determines whether access is safe and reasonable, having regard to AS 4349 (including, where applicable, Table 3.2 of AS 4349.1–2007, Dimensions for reasonable access). Reasonable access does not include moving furniture, stored goods or floor coverings, removing screws, bolts, fastenings or sealants from access covers, or cutting access holes."]},
  {"kind": "clause", "n": "4.17", "paras": ["The Inspector may decline, suspend or end the Inspection, or any part of it, at any time if the Inspector considers conditions at the Site to be unsafe. This includes unsafe structures or electrical installations, suspected hazardous materials, aggressive animals, threatening behaviour, and severe weather. Areas that are not inspected for these reasons are excluded from the Inspection and the Report, and the Price remains payable."]},
  {"kind": "clause", "n": "4.18", "paras": ["Weather, light, occupants, furnishings and stored items may limit what the Inspector is able to see. For example, a roof exterior will not be accessed when it is wet or the wind is unsafe. Houspect may reschedule an Inspection that cannot be carried out properly because of conditions at the Site."]},
  {"kind": "clause", "n": "4.19", "paras": ["If the Inspection cannot be completed because the access or arrangements in this clause are not provided, any further attendance requested by the Client is chargeable at a reasonable additional fee notified by Houspect."]},
  {"kind": "subheading", "text": "Inspection Limits and Exclusions"},
  {"kind": "clause", "n": "4.20", "paras": ["The Report is not an all-encompassing report dealing with a building from every aspect. It is a reasonable attempt to identify significant defects visible at the time of the Inspection. Whether a defect is significant depends to a large degree on the age of the building, and the Inspector may not comment on every minor defect or imperfection."]},
  {"kind": "clause", "n": "4.21", "paras": ["The Inspection is a visual inspection, limited to the areas of the Property that are accessible and visible to the Inspector on the Inspection Date. Unless otherwise agreed, the Inspector does not break apart, dismantle, remove or move objects such as foliage, insulation, floor or wall coverings, linings, furnishings, appliances or personal possessions, and is not able to see inside walls, between floors, inside roofing, behind stored goods or in other concealed or obstructed areas. The Inspector does not dig, gouge, force or carry out other invasive procedures, and will not destructively probe visible timbers without the written permission of the property owner."]},
  {"kind": "clause", "n": "4.22", "paras": ["Unless the Quotation states otherwise, the Inspector is not required to inspect or report on the following, although the Inspector may comment on them where they are readily apparent:"]},
  {"kind": "item", "n": "(a)", "text": "footings below ground;"},
  {"kind": "item", "n": "(b)", "text": "concealed damp-proof course;"},
  {"kind": "item", "n": "(c)", "text": "electrical installations, including smoke detectors, light switches and fittings, TV, sound, communications and security systems;"},
  {"kind": "item", "n": "(d)", "text": "concealed plumbing;"},
  {"kind": "item", "n": "(e)", "text": "the adequacy of roof drainage as installed;"},
  {"kind": "item", "n": "(f)", "text": "gas fittings and fixtures;"},
  {"kind": "item", "n": "(g)", "text": "air-conditioning;"},
  {"kind": "item", "n": "(h)", "text": "automatic garage door mechanisms;"},
  {"kind": "item", "n": "(i)", "text": "swimming pools and associated filtration and similar equipment (a swimming pool should be the subject of a special purpose report by a suitably qualified person);"},
  {"kind": "item", "n": "(j)", "text": "the operation of fireplaces and solid fuel heaters, including chimneys and flues;"},
  {"kind": "item", "n": "(k)", "text": "alarm systems;"},
  {"kind": "item", "n": "(l)", "text": "electrical appliances, such as dishwashers, incinerators, ovens and ducted vacuum systems;"},
  {"kind": "item", "n": "(m)", "text": "paint coatings, except external protective coatings;"},
  {"kind": "item", "n": "(n)", "text": "health hazards (for example, allergies, lead content, asbestos and soil toxicity);"},
  {"kind": "item", "n": "(o)", "text": "timber and metal framing sizes and adequacy;"},
  {"kind": "item", "n": "(p)", "text": "concealed tie-downs and bracing;"},
  {"kind": "item", "n": "(q)", "text": "timber pest activity;"},
  {"kind": "item", "n": "(r)", "text": "soil conditions;"},
  {"kind": "item", "n": "(s)", "text": "control joints;"},
  {"kind": "item", "n": "(t)", "text": "concealed framing timber or any areas concealed by wall linings or sidings; and"},
  {"kind": "item", "n": "(u)", "text": "furniture and accessories."},
  {"kind": "clause", "n": "4.23", "paras": ["Where large structural retaining walls are present, the Client may wish to engage a structural engineer for a special purpose report. The Inspector may, but is not required to, comment on whether an engineer is needed."]},
  {"kind": "clause", "n": "4.24", "paras": ["Houspect does not give advice about asbestos, including whether building materials contain asbestos. If the Inspector suspects that a material may contain asbestos, Houspect may mention it, without obligation, so that the Client can have the matter confirmed by a suitably qualified person. The Client should not treat any such comment as determinative."]},
  {"kind": "section", "n": "5", "title": "REPORT"},
  {"kind": "clause", "n": "5.1", "paras": ["The Report will be drafted from the observations taken by the Inspector during the Inspection and is subject to any Use Conditions."]},
  {"kind": "clause", "n": "5.2", "paras": ["Houspect is only able to comment on defects that are visibly observed on the inspection date. This includes but is not limited to water ingress, subsidence, incorrect levels, and shrinkage of materials. Issues shall be presented in the report based on deemed priority aligned with standard expectations practically permitted in a visual inspection by a registered builder."]},
  {"kind": "clause", "n": "5.3", "paras": ["Houspect will not provide any advice or guidance in respect to the cost to rectify any defects found at the Property or identified in the Report. Any comment made in that regard cannot be relied on to support a claim against Houspect."]},
  {"kind": "clause", "n": "5.4", "paras": ["The opinion of Houspect is limited to as detailed in any written Report and the Client cannot rely on any verbal statement or expressed opinion that is not provided in writing in the Report. Houspect will provide the Works with due care and skill and within a reasonable time, to the extent required by law."]},
  {"kind": "clause", "n": "5.5", "paras": ["Houspect may use various standards and guides when considering whether an item of work is defective. These standards may include: Building Code of Australia, National Construction Code, Australian Standards, the Guide described in clause 5.7 and any other material in which the Inspector considers are relevant to the Works."]},
  {"kind": "clause", "n": "5.6", "paras": ["Houspect will use its best endeavours to deliver the Report within 24 to 48 hours from the Inspection Date, unless the Quotation specifies otherwise. This is a target only. Time is not of the essence, and delay in delivering the Report does not entitle the Client to terminate this Agreement or to reduce the Price."]},
  {"kind": "clause", "n": "5.7", "paras": ["The Guide:"]},
  {"kind": "item", "n": "(a)", "text": "is informative only. It is an advisory document and is not part of the Victorian legislative framework, and legislation, the National Construction Code, a documented Standard and the building contract take precedence over it;"},
  {"kind": "item", "n": "(b)", "text": "does not provide a definitive determination of whether building work is defective, and is applied by the Inspector with reasonable discretion and judgement;"},
  {"kind": "item", "n": "(c)", "text": "applies to domestic building contracts entered into, or building work that commences, on or after 1 August 2026, and is not applied retrospectively. For building work that commenced before that date, Houspect may refer to the edition of the Guide, or other applicable building standard, that was published when the building work commenced; and"},
  {"kind": "item", "n": "(d)", "text": "where applied, is applied by the Inspector in the manner described in Part B (Measurement and Inspection) of the Guide, including inspecting surfaces from a normal viewing position."},
  {"kind": "bullet", "text": "Houspect has tried to categorise our gradings as:"},
  {"kind": "bullet", "text": "New: Self-explanatory/newly built or constructed with none to minimal use."},
  {"kind": "bullet", "text": "Satisfactory: Generally good condition."},
  {"kind": "bullet", "text": "Fair: Starting to look like it needs maintenance."},
  {"kind": "bullet", "text": "Average: Working but needs maintenance within 6 months."},
  {"kind": "bullet", "text": "Poor: Needs replacement."},
  {"kind": "para", "text": "As appropriate to any particular property or material other terms may be used for gradings and to describe condition such as aged, dilapidated, deteriorated, weathered, rusting, delaminated, rotted, decayed, subsided, etc."},
  {"kind": "clause", "n": "5.8", "paras": ["Dimensions given in the Report are approximate only."]},
  {"kind": "clause", "n": "5.9", "paras": ["The Report comments on the items that the Inspector considers relevant and has observed. Where the Report does not comment on an item, the Client should not assume that the item was inspected or that it is free from defect."]},
  {"kind": "section", "n": "6", "title": "COMMON PROPERTY"},
  {"kind": "clause", "n": "6.1", "paras": ["Houspect is under no obligation to differentiate between lot and common property."]},
  {"kind": "clause", "n": "6.2", "paras": ["Should any lot property not be inspected as a result of the Inspector considering it is common property, the Client, subject to Clause 6.3 is to provide notice to the Inspector of any areas missed in the inspection and arrange for a secondary inspection."]},
  {"kind": "clause", "n": "6.3", "paras": ["If no notice under Clause 6.2 is provided within 5 days of the first inspection the Client accepts the Report as provided and has no recourse against Houspect or the Inspector for any failure to inspect relevant areas."]},
  {"kind": "section", "n": "7", "title": "COPYRIGHT"},
  {"kind": "clause", "n": "7.1", "paras": ["The Report is expressly produced for the sole use of the Client for the intended purpose as advised to Houspect. The client may not disseminate or provide the Report to third parties without the written authority of Houspect."]},
  {"kind": "clause", "n": "7.2", "paras": ["The Client agrees that all copyright in the Report vests in Houspect."]},
  {"kind": "clause", "n": "7.3", "paras": ["The Client acknowledges that any breach of this Clause 7 will result in damages to Houspect, and that damages may not be an adequate remedy to protect Houspect’s commercial interests. Any breach of Clause 7 by the Client will result in a debt immediately due and payable to Houspect to the extent of any loss, which includes but is not limited to:"]},
  {"kind": "item", "n": "(a)", "text": "providing the Report at the Price to other prospective purchasers;"},
  {"kind": "item", "n": "(b)", "text": "providing the Report to any other persons for use in relation to the Property or otherwise;"},
  {"kind": "item", "n": "(c)", "text": "providing inspection reports to the market generally."},
  {"kind": "clause", "n": "7.4", "paras": ["Subject to this clause 7 and to payment of the Price, Houspect grants the Client a non-exclusive, non-transferable licence to use the Report, in its entirety, for the purpose advised to Houspect."]},
  {"kind": "clause", "n": "7.5", "paras": ["Only the Client may rely on the Report. Houspect owes no duty and accepts no liability to any other person who receives or relies on the Report, even if Houspect has consented to the Report being provided to that person. The Client may provide the Report, in its entirety, to its legal advisers, finance provider, insurer and other professional advisers for the purpose advised to Houspect, but only on the basis that they are told they may not rely on it."]},
  {"kind": "clause", "n": "7.6", "paras": ["The Report reflects the condition of the Property on the Inspection Date only. Houspect has no obligation to update the Report, and the condition of the Property may change after the Inspection Date."]},
  {"kind": "section", "n": "8", "title": "WHS AND ENVIRONMENT COMPLIANCE"},
  {"kind": "clause", "n": "8.1", "paras": ["Houspect and its Personnel must comply with all Legislative Requirements applicable to the Works; including applicable Work Health and Safety laws (relevant to the jurisdiction in which the Supply is being provided)."]},
  {"kind": "section", "n": "9", "title": "ACCURACY OF INFORMATION"},
  {"kind": "clause", "n": "9.1", "paras": ["In preparation of the Report, Houspect relies upon the assumptions and instructions that are provided to it by the Client."]},
  {"kind": "clause", "n": "9.2", "paras": ["The Client acknowledges that where Houspect relies upon any assumptions or instruction by the Client, Houspect is in no way liable for any error or omission from the Report as a result of those assumptions."]},
  {"kind": "clause", "n": "9.3", "paras": ["Houspect makes no representation and provides no warranty as to the accuracy of any representations, documentation, information or opinions provided to the Client. The Client must make its own investigations and satisfy itself as to the accuracy of any such documentation, information and representations, including those contained in the Report."]},
  {"kind": "section", "n": "10", "title": "LIABILITY"},
  {"kind": "clause", "n": "10.1", "paras": ["Houspect is not liable for any indirect or consequential loss or damage whatsoever arising out of or in connection with the Works whether or not the possibility of such loss or damage was known or foreseeable."]},
  {"kind": "clause", "n": "10.2", "paras": ["The Client releases and indemnifies Houspect for any claims in respect of:"]},
  {"kind": "item", "n": "(a)", "text": "any breach of a term or warranty given (or not given) in this Agreement;"},
  {"kind": "item", "n": "(b)", "text": "damages arising from any invasive inspection requested by the Client."},
  {"kind": "clause", "n": "10.3", "paras": ["To the extent permitted by law, liability under any condition or warranty which cannot legally be excluded is limited to (at Houspect’s option):"]},
  {"kind": "item", "n": "(a)", "text": "performing the Works again; or"},
  {"kind": "item", "n": "(b)", "text": "paying the cost of having the Report supplied again."},
  {"kind": "clause", "n": "10.4", "paras": ["Nothing in this Agreement limits the operation of Part IVAA (Proportionate liability) of the Wrongs Act 1958 (Vic). The Client acknowledges that Houspect is not responsible for loss or damage caused by others, including the builder, vendor, owner, other consultants or any occupier of the Property nor client’s decision to progress not taking further action on any recommendations and remarks made within the report."]},
  {"kind": "clause", "n": "10.5", "paras": ["If the Client considers that the Report does not conform in a material respect with this Agreement, the Client should notify Houspect in writing as soon as reasonably practicable, and where possible within 90 days after delivery of the Report, so that Houspect can review the matter. To the extent permitted by law, Houspect’s liability in respect of any such failure is limited as set out in clause 10.3."]},
  {"kind": "section", "n": "11", "title": "PAYMENT"},
  {"kind": "clause", "n": "11.1", "paras": ["In consideration for Houspect performing the Works, the Client agrees to pay the Price, plus any agreed variations to it, without any right of offset."]},
  {"kind": "clause", "n": "11.2", "paras": ["The Client must pay the Price by the Inspection Date, unless a different payment arrangement has been established through a separate contractor agreement between the Client and Houspect, in which case payment must be made in accordance with that agreement."]},
  {"kind": "clause", "n": "11.3", "paras": ["The Client must raise any dispute with the invoice within 15 Business Days of receipt, failing which the Client shall be forever barred from making a claim in relation to a disputed invoice."]},
  {"kind": "clause", "n": "11.4", "paras": ["Where the Client does not make payment in accordance with Clause 11.1, Houspect will be entitled to claim interest at the rate of 10% per annum on all outstanding amounts."]},
  {"kind": "clause", "n": "11.5", "paras": ["If the Client cancels an Inspection:"]},
  {"kind": "item", "n": "(a)", "text": "on the Inspection Date, but before the Inspector arrives at the Site, a call-out fee of $200 is payable by the Client; or"},
  {"kind": "item", "n": "(b)", "text": "without prior notice, such that Houspect is not told of the cancellation until the Inspector arrives at the Site, the full Price is payable by the Client."},
  {"kind": "clause", "n": "11.6", "paras": ["Where the Client is a preferred client of Houspect, payment of the Price is due within 7 days from the invoice date."]},
  {"kind": "clause", "n": "11.7", "paras": ["Charge-out rates quoted relate to normal work. Work relating to arbitration, mediation, conciliation, expert witness or court appearance, or to other legal matters, is charged separately at Houspect’s rates."]},
  {"kind": "section", "n": "12", "title": "REFERRALS"},
  {"kind": "clause", "n": "12.1", "paras": ["Where requested by the Client, Houspect may arrange or coordinate other specialist inspection or building services to be provided by independent third party consultants or companies, and will be entitled to charge a reasonable fee for the organisation and coordination of the same."]},
  {"kind": "clause", "n": "12.2", "paras": ["These services may include:"]},
  {"kind": "item", "n": "(a)", "text": "plumbing reports;"},
  {"kind": "item", "n": "(b)", "text": "electrical reports;"},
  {"kind": "item", "n": "(c)", "text": "engineering reports;"},
  {"kind": "item", "n": "(d)", "text": "mould reports;"},
  {"kind": "item", "n": "(e)", "text": "toxicology reports;"},
  {"kind": "item", "n": "(f)", "text": "waterproofing reports;"},
  {"kind": "item", "n": "(g)", "text": "pests reports; and"},
  {"kind": "item", "n": "(h)", "text": "asbestos reports."},
  {"kind": "clause", "n": "12.3", "paras": ["In arranging these services or referring the Client to a third party that provides these services, the Client acknowledges that Houspect may be paid a fee for the referral."]},
  {"kind": "clause", "n": "12.4", "paras": ["Houspect does not in any way warrant or guarantee the services provided by these third-parties, including where those reports or observations are included in the Report, and is in no way liable for the services performed by them."]},
  {"kind": "clause", "n": "12.5", "paras": ["Timber pest inspections (which are the subject of AS 4349.3) are not part of the Inspection. Where the Client asks, Houspect may coordinate a timber pest inspection, or other specialist inspection, by an independent provider. Any facilitated inspections through third parties would be a direct engagement of services with such party introduced by Houspect and Houspect does not take any liability nor make any representation of such party works."]},
  {"kind": "section", "n": "13", "title": "REPORT VARIATIONS"},
  {"kind": "clause", "n": "13.1", "paras": ["Houspect may vary the Works as directed by the Client in writing or otherwise prior to the works being undertaken."]},
  {"kind": "clause", "n": "13.2", "paras": ["The Client or Houspect may request a Variation in writing or otherwise prior to the works being undertaken."]},
  {"kind": "clause", "n": "13.3", "paras": ["The price for any Variation to the Works will be added to, or deducted, from the Price as applicable."]},
  {"kind": "clause", "n": "13.4", "paras": ["The Price payable in respect of a Variation will wherever possible be agreed in writing prior to the commencement of the Variation, having regard in the first instance to any agreed rates or sums. In the absence of such agreement, the Price for a Variation will be the total hours worked multiplied by the hourly rate of the inspector plus any costs incurred."]},
  {"kind": "clause", "n": "13.5", "paras": ["If a variation is required in order to comply with any relevant law, the Client must consent."]},
  {"kind": "section", "n": "14", "title": "DISPUTES"},
  {"kind": "clause", "n": "14.1", "paras": ["If a dispute between the parties arises in connection with the Agreement, then either party may by hand or registered post, give the other written notice of the dispute adequately identifying the issues, details and cause of the dispute."]},
  {"kind": "clause", "n": "14.2", "paras": ["Within 14 days of receiving the written notice of the dispute, the parties must attend a conference to resolve or agree on methods to resolve the dispute."]},
  {"kind": "clause", "n": "14.3", "paras": ["If the dispute is not resolved at the conference or within 21 days after the notice in Clause 14.1, either party may commence proceedings."]},
  {"kind": "clause", "n": "14.4", "paras": ["The conference required by clause 14.2 may be conducted as a mediation before a mediator agreed by the parties, which may be a mediator from the Dispute Settlement Centre of Victoria. Each party bears its own costs of the dispute process, and the mediator’s fees are shared equally."]},
  {"kind": "clause", "n": "14.5", "paras": ["Nothing in this clause 14 prevents a party from seeking urgent interlocutory or injunctive relief. Subject to this clause 14, proceedings may be brought in the Victorian Civil and Administrative Tribunal where it has jurisdiction, and otherwise in the courts of Victoria."]},
  {"kind": "clause", "n": "14.6", "paras": ["The parties must continue to perform their obligations under this Agreement while a dispute is being resolved, except to the extent that performance is the subject of the dispute."]},
  {"kind": "section", "n": "15", "title": "DEFAULTS AND TERMINATION"},
  {"kind": "clause", "n": "15.1", "paras": ["Any party may terminate this Contract:"]},
  {"kind": "item", "n": "(a)", "text": "within 14 days of a written notice if there is a breach of the Agreement that is capable of remedy and the other party has failed to rectify that default within that timeframe; or"},
  {"kind": "item", "n": "(b)", "text": "immediately if there is a material breach of this agreement that is not capable of remedy."},
  {"kind": "clause", "n": "15.2", "paras": ["If the Contract is terminated for any reason:"]},
  {"kind": "item", "n": "(a)", "text": "Houspect will be entitled to the unpaid value of the Works completed in accordance with the Agreement immediately prior to termination; and"},
  {"kind": "item", "n": "(b)", "text": "Houspect will be entitled to any costs associated with preparing or providing a report, notes or any other document or information to the Client; and"},
  {"kind": "item", "n": "(c)", "text": "The Client will be entitled to any documents, notes or otherwise in Houspect's possession that have been paid for by the Client."},
  {"kind": "section", "n": "16", "title": "GST"},
  {"kind": "clause", "n": "16.1", "paras": ["The Client must on provision of a valid tax invoice, pay Houspect the amount of GST for which Houspect becomes liable on any supply Houspect makes to the Client in connection with this Agreement."]},
  {"kind": "clause", "n": "16.2", "paras": ["All invoices rendered by Houspect under this Agreement must comply with the GST Laws and must be sufficient to enable the Client to claim any input tax credits which may be available to it."]},
  {"kind": "clause", "n": "16.3", "paras": ["“GST”, “GST Laws” and other terms used in this clause have the meanings used in the A New Tax System (Goods and Supply Tax) Act 1999, except that “GST Laws” includes any applicable rulings issued by the Commissioner of Taxation."]},
  {"kind": "section", "n": "17", "title": "QUOTATION, ACCEPTANCE AND VALIDITY"},
  {"kind": "clause", "n": "17.1", "paras": ["The Quotation is valid for 30 days from the date of the Quotation. After that period, Houspect may withdraw or revise the Quotation."]},
  {"kind": "clause", "n": "17.2", "paras": ["This Agreement is sent to the Client with the Quotation email. No signature is required. The Client is deemed to have accepted the Quotation and this Agreement, and this Agreement is binding on the Client, when the Client replies to and confirms the Quotation by email."]},
  {"kind": "clause", "n": "17.3", "paras": ["A person who replies to and confirms the Quotation on behalf of a company, trust or other person warrants that they have authority to do so, and that person binds the Client by doing so."]},
  {"kind": "clause", "n": "17.4", "paras": ["The parties agree that this Agreement may be entered into, and accepted, by electronic communication, consistent with the Electronic Transactions (Victoria) Act 2000 (Vic)."]},
  {"kind": "clause", "n": "17.5", "paras": ["Any change to the scope, Price or Inspection Date takes effect only when Houspect confirms it in writing, which includes by email."]},
  {"kind": "clause", "n": "17.6", "paras": ["These are the standard terms on which Houspect provides its services. If the Client does not agree to be bound by them, the Client should contact Houspect before the Inspection so that the services are not provided on these terms."]},
  {"kind": "section", "n": "18", "title": "CONSUMER LAW AND VICTORIAN LEGISLATION"},
  {"kind": "clause", "n": "18.1", "paras": ["The Client’s rights under the ACL and the Australian Consumer Law and Fair Trading Act 2012 (Vic) are not affected by this Agreement, to the extent they cannot be excluded."]},
  {"kind": "clause", "n": "18.2", "paras": ["The Works are inspection and reporting services only. Houspect does not carry out, supervise, manage or warrant domestic building work, and this Agreement is not a domestic building contract for the purposes of the Domestic Building Contracts Act 1995 (Vic)."]},
  {"kind": "clause", "n": "18.3", "paras": ["Nothing in the Report is a statement about the Client’s rights against a builder, a vendor or an insurer, including any statutory warranty under section 8 of the Domestic Building Contracts Act 1995 (Vic) or any domestic building insurance. Time limits may apply to those rights. The Client should take legal advice about them."]},
  {"kind": "section", "n": "19", "title": "PRIVACY"},
  {"kind": "clause", "n": "19.1", "paras": ["Houspect shall take all reasonably possible efforts to handle personal information in accordance with the Privacy Act 1988 (Cth) and the Australian Privacy Principles, to the extent they apply to Houspect, and with any other privacy law that applies to it in Victoria (including, where applicable, the Privacy and Data Protection Act 2014 (Vic) and the Health Records Act 2001 (Vic))."]},
  {"kind": "clause", "n": "19.2", "paras": ["Houspect collects personal information about the Client and about occupiers of the Property, such as names, contact details, the address of the Property, access arrangements, and photographs and notes taken during the Inspection. Houspect collects and uses this information to:"]},
  {"kind": "item", "n": "(a)", "text": "provide a Quotation and carry out the Works;"},
  {"kind": "item", "n": "(b)", "text": "prepare the Report and keep records of the Inspection;"},
  {"kind": "item", "n": "(c)", "text": "invoice and collect payment;"},
  {"kind": "item", "n": "(d)", "text": "arrange referrals under clause 12, where the Client asks for them;"},
  {"kind": "item", "n": "(e)", "text": "manage quality and training, and handle complaints and disputes; and"},
  {"kind": "item", "n": "(f)", "text": "comply with its legal obligations."},
  {"kind": "clause", "n": "19.3", "paras": ["Houspect may disclose personal information to its franchisor and related entities, to its Personnel, to service providers that support its business (such as booking, payment, reporting and data storage providers), to professional advisers and insurers, to any referral provider the Client has asked Houspect to engage, and where required or authorised by law. If Houspect discloses personal information overseas, it will take reasonable steps in accordance with the Australian Privacy Principles."]},
  {"kind": "clause", "n": "19.4", "paras": ["The Client must not give Houspect the personal information of another person unless the Client is entitled to do so. Houspect will take reasonable steps to let occupiers and other affected persons know how it handles their information, and the Client should help where it is able to."]},
  {"kind": "clause", "n": "19.5", "paras": ["Houspect takes reasonable steps to keep personal information secure. If an eligible data breach occurs, Houspect will notify the persons and the regulator as required by the Privacy Act 1988 (Cth)."]},
  {"kind": "clause", "n": "19.6", "paras": ["The Client and other individuals may ask to access or correct personal information that Houspect holds about them, or may make a privacy complaint, by writing to Houspect Victoria at PO Box 2521, MOUNT WAVERLEY VIC 3149 or by email to info@houspectvic.com.au."]},
];
